def choose_move(observation):
    def g(key, default=None):
        try:
            return observation.get(key, default)
        except:
            return default

    def to_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except:
                return default
        return default

    def clamp_step(t, s):
        if t > s:
            return 1
        if t < s:
            return -1
        return 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    sx, sy = to_pair(g("self_position", g("position", (0, 0))))
    ox, oy = to_pair(g("opponent_position", g("enemy_position", (sx, sy))))

    w = g("grid_width", g("width", 0))
    h = g("grid_height", g("height", 0))
    try:
        w = int(w)
    except:
        w = 0
    try:
        h = int(h)
    except:
        h = 0

    env = g("environment_name", "resource_collection")
    role = g("self_role", g("role", ""))

    def move_toward(target):
        tx, ty = to_pair(target, (sx, sy))
        return [clamp_step(tx, sx), clamp_step(ty, sy)]

    def move_away(target):
        tx, ty = to_pair(target, (sx, sy))
        return [clamp_step(sx, tx), clamp_step(sy, ty)]

    def best_by_distance(items, prefer_far=False):
        best = None
        best_score = None
        for it in items or []:
            if not (isinstance(it, (list, tuple)) and len(it) >= 2):
                continue
            p = to_pair(it)
            d = manhattan((sx, sy), p)
            score = -d if prefer_far else d
            if best is None or score < best_score:
                best = p
                best_score = score
        return best

    if env == "pursuit_evasion":
        if role == "evader" or role == "runner":
            threats = g("pursuers") or g("enemies") or [g("opponent_position", None)]
            threat = best_by_distance(threats) if isinstance(threats, list) else to_pair(ox, (sx, sy))
            if threat != (0, 0):
                return move_away(threat)
            if w and h:
                corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
                target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
                return move_toward(target)
            return [0, 0]
        return move_toward((ox, oy))

    if env == "territory_control":
        targets = g("unclaimed_cells") or g("neutral_cells") or g("opponent_territory") or g("targets") or []
        target = best_by_distance(targets)
        if target is not None:
            return move_toward(target)
        if w and h:
            cx, cy = w // 2, h // 2
            if (sx, sy) != (cx, cy):
                return move_toward((cx, cy))
        return [0, 0]

    resources = g("resources") or g("resource_positions") or g("food") or []
    target = best_by_distance(resources)
    if target is not None:
        return move_toward(target)

    enemy = to_pair(ox, (sx, sy))
    if manhattan((sx, sy), enemy) <= 2:
        return move_away(enemy)

    if w and h:
        cx, cy = w // 2, h // 2
        return move_toward((cx, cy))

    return [0, 0]

